/**
 * The drawing kit every loader dial is built from. One shader draws almost everything: a flat
 * annulus that can be cut to an angular window (an arc), repeated around the circle (a tick crown,
 * a dash ring), faded along its sweep (a shaded blade) and lit by a travelling highlight (the tick
 * crown catching the accent as it passes). An arc's window and its highlight are uniforms, so an
 * arc that grows, slides or sweeps is a uniform write per frame and never a geometry rebuild.
 *
 * Antialiasing: the radial edges are real geometry, so the renderer's MSAA smooths them. The
 * angular cuts are made in the fragment shader, so they are smoothed there, over one device pixel
 * measured with `fwidth`, or the ends of every arc and every tick would stair-step.
 *
 * Every mesh is flat, transparent and drawn in creation order (`renderOrder`), with depth off: the
 * dial is a stack of layers, and the stack order is the order the variant builds them in. Each
 * layer also sits at its own small `z`, which is what gives the gentle sway its parallax.
 */

import {
  Color,
  Group,
  Mesh,
  MeshBasicMaterial,
  PlaneGeometry,
  RingGeometry,
  SRGBColorSpace,
  ShaderMaterial,
  type BufferGeometry,
  type Material,
  type Object3D,
} from 'three'
import type { Palette, Role } from './palette'

export const TAU = Math.PI * 2

/**
 * `--ease-snap`, cubic-bezier(0.2, 0.8, 0.2, 1), solved exactly: the dial's draw-on and its indexed
 * steps use the same curve as every CSS transition in the system, not an approximation of it.
 */
export function easeSnap(t: number): number {
  if (t <= 0) return 0
  if (t >= 1) return 1
  const [x1, y1, x2, y2] = [0.2, 0.8, 0.2, 1]
  const bez = (u: number, a: number, b: number) => 3 * a * u * (1 - u) ** 2 + 3 * b * u ** 2 * (1 - u) + u ** 3
  // Newton on x(u) = t, then read y(u). x is monotonic for these control points.
  let u = t
  for (let i = 0; i < 8; i++) {
    const x = bez(u, x1, x2) - t
    const dx = 3 * x1 * (1 - u) ** 2 + 6 * (x2 - x1) * u * (1 - u) + 3 * (1 - x2) * u ** 2
    if (Math.abs(x) < 1e-6 || dx === 0) break
    u = Math.min(1, Math.max(0, u - x / dx))
  }
  return bez(u, y1, y2)
}

/** How long one element takes to draw itself on, in seconds. */
export const DRAW_ON = 0.6

/** An indexed move: hold, then snap forward one `step` over `move` seconds, every `period`. The
 *  mechanical cadence of a dial clicking to its next detent, on the system's own easing. */
export function stepped(t: number, period: number, move: number, step: number): number {
  const k = Math.floor(t / period)
  return (k + easeSnap((t - k * period) / move)) * step
}

/** A value that breathes between `min` and `max` with period `period`, starting at `min`. */
export function breathe(t: number, min: number, max: number, period: number): number {
  return min + (max - min) * (0.5 - 0.5 * Math.cos((t / period) * TAU))
}

export function polar(r: number, angle: number): [number, number] {
  return [r * Math.cos(angle), r * Math.sin(angle)]
}

const VERT = /* glsl */ `
varying vec2 vLocal;
void main() {
  vLocal = position.xy;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`

const FRAG = /* glsl */ `
uniform vec3 uColor;
uniform float uOpacity;
uniform float uStart;
uniform float uLength;
uniform float uCount;
uniform float uDuty;
uniform float uFade;
uniform float uHead;
uniform float uHeadWidth;
uniform vec3 uHeadColor;
varying vec2 vLocal;
const float TAU = 6.28318530718;

void main() {
  float r = max(length(vLocal), 1e-4);
  float ang = atan(vLocal.y, vLocal.x);
  float rel = mod(ang - uStart, TAU);
  // One device pixel, as an angle at this radius. fwidth(ang) would spike at atan's +-PI seam.
  float px = length(fwidth(vLocal)) / r;

  float a = 1.0;
  if (uLength < TAU - 1e-4) {
    a *= smoothstep(0.0, px, rel) * (1.0 - smoothstep(uLength - px, uLength, rel));
  }
  if (uCount > 0.0) {
    float cell = fract(rel / TAU * uCount);
    float cellPx = px / TAU * uCount;
    a *= smoothstep(0.0, cellPx, cell) * (1.0 - smoothstep(uDuty - cellPx, uDuty, cell));
  }
  if (uFade > 0.0) {
    float along = clamp(rel / max(uLength, 1e-4), 0.0, 1.0);
    a *= mix(1.0 - uFade, 1.0, along);
  }

  vec3 col = uColor;
  if (uHeadWidth > 0.0) {
    float d = abs(mod(ang - uHead + TAU * 0.5, TAU) - TAU * 0.5);
    float h = 1.0 - smoothstep(0.0, uHeadWidth, d);
    col = mix(col, uHeadColor, h);
    a = min(1.0, a * (1.0 + 1.5 * h));
  }

  a *= uOpacity;
  if (a < 0.002) discard;
  gl_FragColor = vec4(col, a);
  #include <colorspace_fragment>
}
`

export type BandOptions = {
  /** Centre radius of the annulus, in dial units (1 is the dial's outer edge). */
  r: number
  /** Radial width, in dial units. Use `kit.px(n)` for a hairline that stays n CSS pixels wide. */
  w: number
  role: Role
  /** Window start, radians, counter-clockwise from 3 o'clock. */
  start?: number
  /** Window length, radians. TAU (the default) is a full ring. */
  length?: number
  opacity?: number
  /** Repeat the window's content `count` times around the circle, each `duty` of its cell lit. */
  count?: number
  duty?: number
  /** 0: flat. 1: alpha ramps from 0 at the window's start to full at its end. */
  fade?: number
  /** A highlight that lights the band in `head.role` near `head.angle`, `head.width` radians wide. */
  head?: { role: Role; width: number }
  /** Seconds after mount before this element draws itself on. */
  delay?: number
  /** Draw on by growing from the centre rather than by sweeping: for dots and small circles. */
  pop?: boolean
  parent?: Object3D
}

/** A live handle: a variant moves an arc by writing `start`, `length` or `head` each frame, and the
 *  kit's `sync` pushes those (times the draw-on) into the shader. */
export type Band = {
  mesh: Mesh<BufferGeometry, ShaderMaterial>
  mat: ShaderMaterial
  role: Role
  start: number
  length: number
  head: number
  delay: number
  pop: boolean
  opacity: number
  headRole?: Role
}

type Line = { mesh: Mesh<BufferGeometry, MeshBasicMaterial>; role: Role; opacity: number; delay: number }

export class Kit {
  readonly group = new Group()
  readonly bands: Band[] = []
  private readonly lines: Line[] = []
  private readonly owned: { dispose(): void }[] = []
  private palette: Palette
  private readonly pxToWorld: number
  private order = 0
  private z = 0

  constructor(opts: { pxToWorld: number; palette: Palette }) {
    this.pxToWorld = opts.pxToWorld
    this.palette = opts.palette
  }

  /** n CSS pixels, in dial units, for this loader's rendered size. */
  px(n: number): number {
    return n * this.pxToWorld
  }

  /** Sets the depth for every element created after it. */
  layer(z: number): this {
    this.z = z
    return this
  }

  /** A group at the current depth: the variant rotates it to move everything inside together. */
  node(parent: Object3D = this.group): Group {
    const g = new Group()
    g.position.z = this.z
    parent.add(g)
    return g
  }

  band(o: BandOptions): Band {
    const inner = Math.max(0, o.r - o.w / 2)
    const outer = o.r + o.w / 2
    const segments = Math.max(32, Math.ceil(outer * 160))
    const geometry = new RingGeometry(inner, outer, segments, 1)
    const mat = new ShaderMaterial({
      vertexShader: VERT,
      fragmentShader: FRAG,
      transparent: true,
      depthTest: false,
      depthWrite: false,
      uniforms: {
        uColor: { value: new Color() },
        uOpacity: { value: 1 },
        uStart: { value: o.start ?? 0 },
        uLength: { value: 0 },
        uCount: { value: o.count ?? 0 },
        uDuty: { value: o.duty ?? 0.5 },
        uFade: { value: o.fade ?? 0 },
        uHead: { value: 0 },
        uHeadWidth: { value: o.head?.width ?? 0 },
        uHeadColor: { value: new Color() },
      },
    })
    const mesh = new Mesh(geometry, mat)
    mesh.renderOrder = this.order++
    if (!o.parent) mesh.position.z = this.z
    ;(o.parent ?? this.group).add(mesh)
    this.owned.push(geometry, mat)
    const band: Band = {
      mesh,
      mat,
      role: o.role,
      start: o.start ?? 0,
      length: o.length ?? TAU,
      head: 0,
      delay: o.delay ?? 0,
      pop: o.pop ?? false,
      opacity: o.opacity ?? 1,
      headRole: o.head?.role,
    }
    this.bands.push(band)
    this.tint(band)
    return band
  }

  /** A solid dot of radius `radius` (dial units) centred at (x, y). */
  dot(x: number, y: number, radius: number, role: Role, opts: { delay?: number; parent?: Object3D; opacity?: number } = {}): Band {
    const band = this.band({ r: radius / 2, w: radius, role, pop: true, ...opts })
    band.mesh.position.x = x
    band.mesh.position.y = y
    return band
  }

  /** A hollow circle: a hairline ring of radius `radius` centred at (x, y). */
  circle(
    x: number,
    y: number,
    radius: number,
    w: number,
    role: Role,
    opts: { delay?: number; parent?: Object3D; count?: number; duty?: number; opacity?: number } = {}
  ): Band {
    const band = this.band({ r: radius, w, role, pop: true, ...opts })
    band.mesh.position.x = x
    band.mesh.position.y = y
    return band
  }

  /** A straight hairline from (x1, y1) to (x2, y2). Draws on from its first point. */
  line(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    w: number,
    role: Role,
    opts: { delay?: number; parent?: Object3D; opacity?: number } = {}
  ): Mesh {
    const length = Math.hypot(x2 - x1, y2 - y1)
    const geometry = new PlaneGeometry(length, w)
    geometry.translate(length / 2, 0, 0)
    const mat = new MeshBasicMaterial({ transparent: true, depthTest: false, depthWrite: false })
    const mesh = new Mesh(geometry, mat)
    mesh.position.set(x1, y1, opts.parent ? 0 : this.z)
    mesh.rotation.z = Math.atan2(y2 - y1, x2 - x1)
    mesh.renderOrder = this.order++
    ;(opts.parent ?? this.group).add(mesh)
    this.owned.push(geometry, mat)
    const line: Line = { mesh, role, opacity: opts.opacity ?? 1, delay: opts.delay ?? 0 }
    this.lines.push(line)
    this.tintLine(line)
    return mesh
  }

  setPalette(palette: Palette): void {
    this.palette = palette
    for (const band of this.bands) this.tint(band)
    for (const line of this.lines) this.tintLine(line)
  }

  /** Writes every handle's current state into its shader, scaled by its draw-on at time `t`. */
  sync(t: number): void {
    for (const band of this.bands) {
      const drawn = easeSnap((t - band.delay) / DRAW_ON)
      const u = band.mat.uniforms
      u.uStart.value = band.start
      u.uHead.value = band.head
      if (band.pop) {
        u.uLength.value = drawn > 0 ? band.length : 0
        band.mesh.scale.setScalar(Math.max(drawn, 1e-3))
      } else {
        u.uLength.value = band.length * drawn
      }
    }
    for (const line of this.lines) {
      line.mesh.scale.x = Math.max(easeSnap((t - line.delay) / DRAW_ON), 1e-3)
    }
  }

  dispose(): void {
    for (const item of this.owned) item.dispose()
    this.owned.length = 0
  }

  private tint(band: Band): void {
    const c = this.palette[band.role]
    const u = band.mat.uniforms
    ;(u.uColor.value as Color).setRGB(c.r, c.g, c.b, SRGBColorSpace)
    u.uOpacity.value = c.a * band.opacity
    if (band.headRole) {
      const h = this.palette[band.headRole]
      ;(u.uHeadColor.value as Color).setRGB(h.r, h.g, h.b, SRGBColorSpace)
    }
  }

  private tintLine(line: Line): void {
    const c = this.palette[line.role]
    const mat = line.mesh.material as Material & MeshBasicMaterial
    mat.color.setRGB(c.r, c.g, c.b, SRGBColorSpace)
    mat.opacity = c.a * line.opacity
  }
}

import { useEffect, useRef, useState, type HTMLAttributes, type Ref } from 'react'
import { cn } from '../../../lib/cn'
import { motionAllowed, onReducedMotionChange } from '../../../fx/core/gate'
import { hasWebGL2 } from '../../../fx/core/webgl'
import { Spinner } from '../spinner/Spinner'
import { readPalette } from './palette'
import type { LoaderVariant } from './variants'

/** CSS box per size. The renderer draws at the same size, so a 1px hairline stays 1px. */
const SIZE = {
  sm: { className: 'w-24 h-24', px: 96 },
  md: { className: 'w-40 h-40', px: 160 },
  lg: { className: 'w-60 h-60', px: 240 },
} as const

/** `role` is excluded for the same reason as Spinner's: `label` is the sole source of
 *  role="status", and a role arriving in `rest` would silently replace it. */
export type LoadingAnimationProps = Omit<HTMLAttributes<HTMLDivElement>, 'role'> & {
  /** `aperture` (default): shaded blades indexing round a spinning core. `gyro`: nested rings
   *  turning against each other. `reticle`: a progress ring filling from a 12 o'clock marker. */
  variant?: LoaderVariant
  /** A 96px, 160px or 240px square. @default 'md' */
  size?: 'sm' | 'md' | 'lg'
  /** Visually hidden status text. Passing it makes the loader a live region. */
  label?: string
  ref?: Ref<HTMLDivElement>
  role?: never
}

/**
 * A full-panel wait: an animated instrument dial drawn in WebGL, in the theme's own greys with the
 * signal accent on the one element reporting progress. For a wait inside a line of text or a
 * control, use Spinner.
 *
 * The dial is decoration over a status: the canvas is aria-hidden and `label` carries the meaning.
 * Under reduced motion (or save-data) it renders one still frame and never starts a loop; without
 * WebGL it shows the Conveyor spinner in the same box.
 */
export function LoadingAnimation({ variant = 'aperture', size = 'md', label, className, ref, ...rest }: LoadingAnimationProps) {
  const stage = useRef<HTMLDivElement>(null)
  const [failed, setFailed] = useState(() => !hasWebGL2())
  const [animate, setAnimate] = useState(() => motionAllowed())
  const [ready, setReady] = useState(false)

  useEffect(() => onReducedMotionChange(reduced => setAnimate(motionAllowed(reduced))), [])

  useEffect(() => {
    const host = stage.current
    if (failed || !host) return
    // The canvas is created here, not in JSX: a disposed renderer loses its context for good, so
    // every mount (Strict Mode's replay included) needs a canvas of its own.
    const canvas = document.createElement('canvas')
    canvas.className = 'block w-full h-full'
    host.appendChild(canvas)
    let dispose: (() => void) | undefined
    let cancelled = false
    import('./scene')
      .then(({ mountLoader }) => {
        if (cancelled) return
        dispose = mountLoader(canvas, { variant, sizePx: SIZE[size].px, animate, readPalette: () => readPalette(host) })
        setReady(true)
      })
      .catch(() => {
        if (!cancelled) setFailed(true)
      })
    return () => {
      cancelled = true
      dispose?.()
      canvas.remove()
      setReady(false)
    }
  }, [variant, size, animate, failed])

  return (
    <div
      ref={ref}
      role={label ? 'status' : undefined}
      data-variant={variant}
      className={cn('relative inline-grid place-items-center max-w-full aspect-square shrink-0', SIZE[size].className, className)}
      {...rest}
    >
      {failed ? (
        <span aria-hidden="true">
          <Spinner variant="conveyor" size={size} />
        </span>
      ) : (
        <div
          ref={stage}
          aria-hidden="true"
          className={cn(
            'absolute inset-0 transition-opacity [transition-duration:var(--duration-base)] motion-reduce:transition-none',
            ready ? 'opacity-100' : 'opacity-0'
          )}
        />
      )}
      {label ? <span className="sr-only">{label}</span> : null}
    </div>
  )
}

/**
 * The loader's colours, read from the semantic tokens at runtime rather than restated here, so a
 * theme flip or a token change reaches the WebGL scene the same way it reaches every other
 * component. No three.js import: this runs on the page side, before the scene chunk loads.
 */

export type Rgba = { r: number; g: number; b: number; a: number }

/** The five roles every dial draws with. Three greys for structure, one faint for guides, and the
 *  signal accent for the single moving element that says "working". */
export type Role = 'bright' | 'mid' | 'dim' | 'faint' | 'accent'
export type Palette = Record<Role, Rgba>

/**
 * Role to token. `bright` is text.primary and `mid` text.secondary, the same two steps the docs
 * copy uses, so the dial reads at the page's own contrast in both themes. `dim` is border.control,
 * the grey every unbevelled control draws its outline in; `faint` is border.hairline.strong,
 * alpha included. `accent` is accent.signal.fill, as on Spinner's arc.
 */
const TOKENS: Record<Role, string> = {
  bright: '--color-text-primary',
  mid: '--color-text-secondary',
  dim: '--color-border-control',
  faint: '--color-border-hairline-strong',
  accent: '--color-accent-signal-fill',
}

/** Reads the `rgb()` / `rgba()` strings `getComputedStyle` produces, comma or space form. Returns
 *  null rather than a default colour, so an unreadable token is visible as a failure. */
export function parseCssColor(value: string): Rgba | null {
  const match = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/.exec(value.trim())
  if (!match) return null
  const [, r, g, b, alpha] = match
  const a = alpha === undefined ? 1 : alpha.endsWith('%') ? parseFloat(alpha) / 100 : parseFloat(alpha)
  return { r: Number(r) / 255, g: Number(g) / 255, b: Number(b) / 255, a }
}

/**
 * Resolves each role's token in the cascade of `host`, so a loader inside a section with its own
 * `data-theme` gets that section's colours. A probe span inherits the custom properties and
 * reports the computed colour; it lives for the length of this call only.
 */
export function readPalette(host: Element): Palette {
  const probe = document.createElement('span')
  probe.style.display = 'none'
  host.appendChild(probe)
  try {
    const out = {} as Palette
    for (const role of Object.keys(TOKENS) as Role[]) {
      probe.style.color = `var(${TOKENS[role]})`
      out[role] = parseCssColor(getComputedStyle(probe).color) ?? { r: 0.5, g: 0.5, b: 0.5, a: 1 }
    }
    return out
  } finally {
    probe.remove()
  }
}

/**
 * The WebGL side of LoadingAnimation, and the only module that imports the renderer. The component
 * reaches it through a dynamic `import()`, so three.js is its own chunk: a page that never renders
 * a loader never downloads it.
 *
 * Built on the shared effects core (`src/fx/core`): `createLoop` pauses while
 * the tab is hidden or the dial is scrolled out of view, and `dprCap` caps the pixel ratio on a
 * low-tier device.
 */

import { PerspectiveCamera, Scene, WebGLRenderer } from 'three'
import { createLoop } from '../../../fx/core/loop'
import { dprCap } from '../../../fx/core/quality'
import { Kit } from './kit'
import type { Palette } from './palette'
import { LOADER_VARIANTS, type LoaderVariant } from './variants'

/** Half the visible height, in dial units: the dial's radius is 1, plus room for the sway. */
const EXTENT = 1.1
const FOV = 30

/** The pose shown as the still frame under reduced motion: every element drawn on, the progress
 *  arcs part-way round. Chosen by eye, and fixed, so the still frame is the same on every load. */
export const STILL_T = 4.2

export type MountOptions = {
  variant: LoaderVariant
  /** The dial's CSS size, which sets how wide a "1px" hairline is in dial units. */
  sizePx: number
  animate: boolean
  readPalette(): Palette
}

export function mountLoader(canvas: HTMLCanvasElement, opts: MountOptions): () => void {
  const renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'low-power' })
  renderer.setPixelRatio(dprCap())
  renderer.setSize(opts.sizePx, opts.sizePx, false)
  renderer.setClearColor(0x000000, 0)

  const camera = new PerspectiveCamera(FOV, 1, 0.1, 20)
  camera.position.z = EXTENT / Math.tan(((FOV / 2) * Math.PI) / 180)

  const kit = new Kit({ pxToWorld: (2 * EXTENT) / opts.sizePx, palette: opts.readPalette() })
  const update = LOADER_VARIANTS[opts.variant](kit)
  const scene = new Scene()
  scene.add(kit.group)

  const draw = (t: number, sway: boolean) => {
    update(t)
    kit.sync(t)
    // A slow two-axis sway, a few degrees at most: the layers sit at different depths, so the
    // sway is what reads as depth. Off in the still frame, which must be the dial face-on.
    kit.group.rotation.x = sway ? Math.sin(t * 0.7) * 0.09 : 0
    kit.group.rotation.y = sway ? Math.cos(t * 0.53) * 0.09 : 0
    renderer.render(scene, camera)
  }

  let t = 0
  const loop = createLoop({
    el: canvas,
    frame(dt) {
      t += dt
      draw(t, true)
    },
  })
  if (opts.animate) loop.start()
  else draw(STILL_T, false)

  // Colours only change when the theme does. Same trigger the signal grid listens to.
  const mo = new MutationObserver(() => {
    kit.setPalette(opts.readPalette())
    if (!opts.animate) draw(STILL_T, false)
  })
  mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] })

  return () => {
    mo.disconnect()
    loop.dispose()
    kit.dispose()
    renderer.dispose()
    // Browsers cap live WebGL contexts (Chrome at 16) and drop the oldest past it. A docs page that
    // mounts and unmounts loaders must hand each context back, not wait for garbage collection.
    renderer.forceContextLoss()
  }
}

/**
 * The three loader dials. Each builder lays its elements out once, through the kit, and returns
 * `update(t)`: a pure function of seconds since mount that poses every moving part. Nothing reads
 * the previous frame, so any moment can be reproduced from `t` alone (the reduced-motion still
 * frame is exactly that, one call at a fixed `t`).
 *
 * Shared grammar, so the three read as one family:
 *   - Everything draws itself on at mount, outside in, as the system's draw-on motif (M2) does
 *     for a hairline. `delay` staggers the layers.
 *   - Two tempos. Continuous drift for the structure, and an indexed snap (`stepped`) for the one
 *     mechanism in each dial that "clicks" to its next detent on `--ease-snap`.
 *   - One accent element per dial, and it is always the one reporting progress. Greys do the rest.
 *
 * Angles are radians, counter-clockwise from 3 o'clock; clockwise motion is negative. Radii are
 * dial units, 1 at the outer edge.
 */

import { TAU, breathe, polar, stepped, type Kit } from './kit'

export type LoaderVariant = 'aperture' | 'gyro' | 'reticle'
type Builder = (kit: Kit) => (t: number) => void

const TOP = Math.PI / 2

/**
 * Aperture. A tick crown, a heavy outer ring carrying the progress arc, and five shaded blades that
 * index round one detent at a time around a spinning segmented core, like a lens stopping down.
 */
const aperture: Builder = k => {
  // Crown: 72 fine ticks, and every sixth a longer one. The accent arc's head lights the ticks it
  // passes, so the crown reads the sweep instead of ignoring it.
  k.layer(0)
  const crown = k.band({ r: 0.958, w: 0.045, role: 'dim', count: 72, duty: 0.2, head: { role: 'accent', width: 0.32 } })
  k.band({ r: 0.95, w: 0.065, role: 'mid', count: 12, duty: 0.035 })
  k.band({ r: 0.905, w: k.px(2), role: 'mid', delay: 0.05 })

  // Progress track: a faint hairline, grey segments drifting one way, the accent arc sweeping the
  // other and breathing as it goes.
  k.layer(0.03)
  k.band({ r: 0.868, w: k.px(1), role: 'faint', delay: 0.1 })
  const drift = k.node()
  k.band({ r: 0.868, w: k.px(5), role: 'faint', start: -0.45, length: 1.05, parent: drift, delay: 0.12 })
  k.band({ r: 0.868, w: k.px(5), role: 'dim', start: 3.5, length: 0.8, parent: drift, delay: 0.14 })
  const sweep = k.band({ r: 0.868, w: k.px(5), role: 'accent', delay: 0.1 })

  k.layer(0.05)
  const guides = k.node()
  for (const [start, length] of [[2.3, 1.25], [4.05, 0.85], [5.25, 0.5]] as const) {
    k.band({ r: 0.83, w: k.px(1), role: 'dim', start, length, parent: guides, delay: 0.16 })
  }
  const orbit = k.node()
  k.dot(...polar(0.775, 1.0), k.px(2.5), 'bright', { parent: orbit, delay: 0.3 })
  k.dot(...polar(0.775, -1.62), k.px(2), 'bright', { parent: orbit, delay: 0.34 })
  k.circle(...polar(0.775, 3.35), k.px(3.5), k.px(1), 'mid', { parent: orbit, delay: 0.38 })

  k.layer(0.08)
  k.band({ r: 0.645, w: k.px(1.5), role: 'mid', delay: 0.18 })
  k.band({ r: 0.615, w: k.px(1), role: 'faint', delay: 0.2 })

  // Blades: a lit sector fading along its sweep, and a fan of hairline stripes whose starts step
  // back from ring to ring.
  k.layer(0.11)
  const blades = k.node()
  const bladeSpan = TAU / 5 - 0.09
  for (let i = 0; i < 5; i++) {
    const start = (i * TAU) / 5
    k.band({ r: 0.39, w: 0.38, role: 'bright', start, length: bladeSpan, fade: 1, opacity: 0.14, parent: blades, delay: 0.25 + i * 0.04 })
    for (let j = 0; j < 6; j++) {
      const offset = 0.34 - j * 0.055
      k.band({
        r: 0.3 + j * 0.048,
        w: k.px(1),
        role: 'dim',
        start: start + offset,
        length: bladeSpan - offset - 0.03,
        parent: blades,
        delay: 0.3 + i * 0.04 + j * 0.02,
      })
    }
  }

  k.layer(0.15)
  const core = k.node()
  const coreRoles = ['bright', 'dim', 'mid', 'bright', 'faint'] as const
  coreRoles.forEach((role, i) =>
    k.band({ r: 0.155, w: 0.055, role, start: (i * TAU) / 5, length: TAU / 5 - 0.16, parent: core, delay: 0.4 + i * 0.03 })
  )
  k.band({ r: 0.215, w: k.px(1), role: 'faint', delay: 0.42 })

  return t => {
    // Clockwise sweep. Moving clockwise, the leading end is the window's start (its lowest angle),
    // so the head is `start` and the arc trails counter-clockwise behind it, stretching and
    // shortening every 2.2s. The crown lights at the head, ahead of the arc, never at its tail.
    const head = TOP - t * 1.35
    sweep.length = breathe(t, 0.55, 1.9, 2.2)
    sweep.start = head
    crown.head = head
    drift.rotation.z = t * 0.16
    guides.rotation.z = -t * 0.07
    orbit.rotation.z = t * 0.28
    // One blade width per detent, every 1.8s, plus a slow creep so the blades never fully rest.
    blades.rotation.z = -stepped(t, 1.8, 0.55, TAU / 5) - t * 0.06
    core.rotation.z = t * 1.7
  }
}

/**
 * Gyro. Nested thick rings turning against each other, thin orbit arcs that carry a bead at each
 * end and stretch as they run, and a dotted trace chasing round the lower half.
 */
const gyro: Builder = k => {
  k.layer(0)
  const outer = k.node()
  k.band({ r: 0.93, w: k.px(1), role: 'faint', start: 1.9, length: 2.5, parent: outer })
  k.band({ r: 0.93, w: k.px(1), role: 'faint', start: 5.0, length: 0.9, parent: outer, delay: 0.04 })

  // Long orbit arc on the right, bead at its leading end. The bead rides a node rotated to the
  // arc's end, so it moves by rotation and never by a per-frame position write.
  k.layer(0.02)
  const arcC = k.band({ r: 0.86, w: k.px(1), role: 'mid', delay: 0.06 })
  const beadC = k.node()
  k.dot(0.86, 0, k.px(2.5), 'mid', { parent: beadC, delay: 0.3 })

  const trace = k.band({ r: 0.79, w: k.px(2.2), role: 'bright', count: 90, duty: 0.4, opacity: 0.8, delay: 0.1 })

  k.layer(0.05)
  const arcA = k.band({ r: 0.72, w: k.px(1.5), role: 'bright', delay: 0.12 })
  const beadA1 = k.node()
  const beadA2 = k.node()
  k.dot(0.72, 0, k.px(3), 'bright', { parent: beadA1, delay: 0.35 })
  k.dot(0.72, 0, k.px(3), 'bright', { parent: beadA2, delay: 0.35 })

  const arcB = k.band({ r: 0.665, w: k.px(1), role: 'mid', delay: 0.14 })
  const beadB = k.node()
  k.dot(0.665, 0, k.px(2.5), 'mid', { parent: beadB, delay: 0.38 })

  // Middle ring: a faint full band, three grey segments and the accent segment, all turning
  // together counter-clockwise, with the spokes fixed to it.
  k.layer(0.08)
  const middle = k.node()
  k.band({ r: 0.59, w: 0.055, role: 'faint', opacity: 0.6, parent: middle, delay: 0.16 })
  k.band({ r: 0.59, w: 0.055, role: 'mid', start: 2.2, length: 0.85, parent: middle, delay: 0.2 })
  k.band({ r: 0.59, w: 0.055, role: 'dim', start: 3.15, length: 1.0, parent: middle, delay: 0.22 })
  k.band({ r: 0.59, w: 0.055, role: 'accent', start: 0.35, length: 1.15, parent: middle, delay: 0.18 })
  k.line(...polar(0.41, 0.52), ...polar(0.86, 0.52), k.px(1), 'mid', { parent: middle, delay: 0.3 })
  k.line(...polar(0.41, -TOP), ...polar(0.97, -TOP), k.px(1), 'faint', { parent: middle, delay: 0.32 })
  k.line(...polar(0.62, 2.62), ...polar(0.74, 2.62), k.px(1), 'mid', { parent: middle, delay: 0.34 })
  k.dot(...polar(0.745, 2.62), k.px(2.5), 'mid', { parent: middle, delay: 0.4 })

  // Inner segmented ring: eight thick blocks, two lit, turning clockwise on an indexed step.
  k.layer(0.12)
  const inner = k.node()
  const innerRoles = ['faint', 'bright', 'faint', 'faint', 'faint', 'bright', 'faint', 'dim'] as const
  innerRoles.forEach((role, i) =>
    k.band({ r: 0.35, w: 0.09, role, start: (i * TAU) / 8, length: TAU / 8 - 0.05, parent: inner, delay: 0.24 + i * 0.03 })
  )
  k.band({ r: 0.275, w: k.px(1), role: 'faint', delay: 0.3 })

  return t => {
    outer.rotation.z = t * 0.1
    arcC.length = 1.9
    arcC.start = -0.75 - t * 0.28
    beadC.rotation.z = arcC.start + arcC.length

    trace.length = 1.9
    trace.start = 3.3 - t * 0.8

    // The bright orbit stretches and contracts as it runs clockwise, a bead pinned to each end.
    arcA.length = breathe(t, 0.7, 1.7, 2.4)
    arcA.start = 0.3 - t * 0.75
    beadA1.rotation.z = arcA.start
    beadA2.rotation.z = arcA.start + arcA.length

    arcB.length = 0.9
    arcB.start = 1.75 + t * 0.6
    beadB.rotation.z = arcB.start + arcB.length

    middle.rotation.z = t * 0.45
    inner.rotation.z = -stepped(t, 1.5, 0.5, TAU / 8) - t * 0.35
  }
}

/**
 * Reticle. A fine double outer ring with orbiting markers, a progress arc that fills clockwise from
 * the 12 o'clock marker and then drains after itself, and an inner bezel whose bright arc clicks a
 * quarter turn at a time over dim, slowly turning blades.
 */
const reticle: Builder = k => {
  k.layer(0)
  k.band({ r: 0.975, w: k.px(1), role: 'mid' })
  const dashes = k.band({ r: 0.943, w: k.px(2.5), role: 'faint', count: 160, duty: 0.35, delay: 0.04 })
  k.band({ r: 0.9, w: k.px(1.5), role: 'mid', delay: 0.06 })

  k.layer(0.02)
  const progress = k.band({ r: 0.9, w: k.px(3.5), role: 'accent', delay: 0.1 })
  const tip = k.node()
  k.dot(0.9, 0, k.px(3), 'accent', { parent: tip, delay: 0.4 })

  // Fixed markers at 12, 3 and 6 o'clock.
  k.circle(0, 0.9, k.px(4), k.px(1), 'bright', { delay: 0.2 })
  k.circle(0, 0.9, k.px(9), k.px(1), 'faint', { count: 16, duty: 0.5, delay: 0.24 })
  k.line(0, 0.83, 0, 0.975, k.px(1), 'bright', { delay: 0.2 })
  k.circle(0.9, 0, k.px(3), k.px(1), 'mid', { delay: 0.26 })
  k.line(0.85, 0, 1.0, 0, k.px(1), 'mid', { delay: 0.26 })
  k.circle(0, -0.9, k.px(3), k.px(1), 'mid', { delay: 0.28 })
  k.circle(0, -0.9, k.px(9), k.px(1), 'faint', { count: 16, duty: 0.5, delay: 0.3 })

  k.layer(0.05)
  const satellites = k.node()
  k.circle(...polar(0.8, 3.55), 0.075, k.px(1), 'mid', { parent: satellites, delay: 0.3 })
  k.circle(...polar(0.8, 0.45), 0.06, k.px(1), 'faint', { parent: satellites, delay: 0.32 })
  k.dot(...polar(0.83, 2.62), k.px(2.5), 'bright', { parent: satellites, delay: 0.34 })
  ;[
    [3.86, 2],
    [3.93, 1.6],
    [4.0, 1.2],
  ].forEach(([angle, size], i) => k.dot(...polar(0.8, angle), k.px(size), 'mid', { parent: satellites, delay: 0.36 + i * 0.03 }))
  k.circle(...polar(0.8, -0.95), k.px(2.5), k.px(1), 'mid', { parent: satellites, delay: 0.42 })

  k.layer(0.08)
  k.band({ r: 0.63, w: k.px(1.5), role: 'mid', delay: 0.14 })
  k.band({ r: 0.6, w: k.px(1), role: 'faint', delay: 0.16 })
  const bezel = k.band({ r: 0.574, w: k.px(4), role: 'bright', start: TOP - 0.55, length: 1.1, delay: 0.22 })
  const brackets = k.node()
  k.band({ r: 0.556, w: k.px(1.5), role: 'mid', start: Math.PI - 0.35, length: 0.7, parent: brackets, delay: 0.24 })
  k.band({ r: 0.556, w: k.px(1.5), role: 'mid', start: -0.35, length: 0.7, parent: brackets, delay: 0.24 })
  k.band({ r: 0.574, w: k.px(1), role: 'dim', start: -TOP - 0.4, length: 0.8, delay: 0.26 })

  k.layer(0.11)
  const blades = k.node()
  for (let i = 0; i < 5; i++) {
    k.band({ r: 0.31, w: 0.38, role: 'bright', start: (i * TAU) / 5, length: TAU / 5 - 0.1, fade: 1, opacity: 0.1, parent: blades, delay: 0.3 + i * 0.04 })
  }

  const CYCLE = 2.6
  const FILL = 0.6
  return t => {
    dashes.start = -t * 0.05
    // Fill clockwise from 12 o'clock, then drain after itself: the tail chases the head round.
    const p = (t % CYCLE) / CYCLE
    if (p < FILL) {
      progress.length = Math.max(1e-3, stepEase(p / FILL) * TAU)
      progress.start = TOP - progress.length
      tip.rotation.z = progress.start
    } else {
      progress.length = Math.max(1e-3, (1 - stepEase((p - FILL) / (1 - FILL))) * TAU)
      progress.start = TOP - TAU
      tip.rotation.z = progress.start + progress.length
    }
    satellites.rotation.z = t * 0.12
    bezel.start = TOP - 0.55 + stepped(t, 1.4, 0.45, TAU / 4)
    brackets.rotation.z = -t * 0.3
    blades.rotation.z = -t * 0.2
  }
}

/** Smoothstep: the progress fill eases in and out of each phase, so the turn at full is a pause. */
function stepEase(x: number): number {
  const c = Math.min(1, Math.max(0, x))
  return c * c * (3 - 2 * c)
}

export const LOADER_VARIANTS: Record<LoaderVariant, Builder> = { aperture, gyro, reticle }

/**
 * Should an effect run at all?
 *
 * Every effect has a static fallback that the component itself always renders as an
 * alternative — a still frame, a plain block. The effect enhances it; it never replaces
 * content that would otherwise be missing. A "no" here is the same page, still legible and
 * still usable. (This is a client-rendered app — `index.html` ships an empty `#root` — so the
 * fallback exists for a reader who has JS but not motion, not for a reader with no JS at all.)
 */

export function prefersReducedMotion(): boolean {
  return window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false
}

export function prefersSaveData(): boolean {
  const c = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection
  return c?.saveData === true
}

/** `?fx=force` lets a reviewer see effects with OS reduced-motion on. Never overrides save-data. */
function forced(): boolean {
  try {
    return new URLSearchParams(location.search).get('fx') === 'force'
  } catch {
    return false
  }
}

/**
 * A data-saver user's bytes are never spent, even for a reviewer forcing effects —
 * save-data is checked before `?fx=force` and short-circuits it.
 */
export function motionAllowed(reduced = prefersReducedMotion()): boolean {
  if (prefersSaveData()) return false
  if (forced()) return true
  return !reduced
}

export function onReducedMotionChange(fn: (reduced: boolean) => void): () => void {
  if (!window.matchMedia) return () => {}
  const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
  const handler = (e: MediaQueryListEvent) => fn(e.matches)
  mq.addEventListener('change', handler)
  return () => mq.removeEventListener('change', handler)
}

/**
 * Can this page get a WebGL2 context at all?
 *
 * Asked once per page, on a throwaway canvas, and remembered: a context a three.js scene cannot
 * get is a context it will not try to use, and its static fallback renders instead. The probe's
 * own context is released straight away, because browsers cap how many a page may hold.
 *
 * Read by the `LoadingAnimation` atom and by the demo homepage's hero scene.
 */

let support: boolean | null = null

export function hasWebGL2(): boolean {
  if (support !== null) return support
  try {
    const probe = document.createElement('canvas')
    const gl = probe.getContext('webgl2')
    support = !!gl
    ;(gl as WebGL2RenderingContext | null)?.getExtension('WEBGL_lose_context')?.loseContext()
  } catch {
    support = false
  }
  return support
}

/**
 * The render-loop backbone for anything that animates on a canvas. Today that is the
 * LoadingAnimation atom's three.js scene.
 *
 * Two rules: nothing runs while the tab is hidden, nothing runs while the element is
 * off screen. So at most one heavy effect animates at a time.
 */

export interface LoopHandle {
  start(): void
  stop(): void
  dispose(): void
  readonly running: boolean
}

interface LoopOptions {
  frame(dt: number): void
  el: Element
  threshold?: number
}

/** A long frame (tab wake, GC) must slow motion, not teleport it. */
const MAX_DT = 0.05

export function createLoop(opts: LoopOptions): LoopHandle {
  const { frame, el, threshold = 0.05 } = opts

  let raf = 0
  let last = 0
  // Optimistic: an IntersectionObserver that never fires must not strand the effect.
  let visible = true
  let wanted = false
  let disposed = false

  const tick = (now: number) => {
    if (disposed) return
    const dt = last === 0 ? 1 / 60 : Math.min((now - last) / 1000, MAX_DT)
    last = now
    frame(dt)
    // `frame` itself may call `stop()` from inside its own callback: `pause()` at that point cancels an id that has already fired, which does
    // nothing, so without this check the unconditional reschedule below would undo the stop on
    // the very same tick.
    if (!wanted || disposed) {
      raf = 0
      return
    }
    raf = requestAnimationFrame(tick)
  }

  const resume = () => {
    if (disposed || raf !== 0) return
    if (!wanted || !visible || document.hidden) return
    last = 0
    raf = requestAnimationFrame(tick)
  }

  const pause = () => {
    if (raf !== 0) cancelAnimationFrame(raf)
    raf = 0
  }

  const io = new IntersectionObserver(
    (entries) => {
      visible = entries.some((e) => e.isIntersecting)
      visible ? resume() : pause()
    },
    { threshold },
  )
  io.observe(el)

  const onVisibility = () => (document.hidden ? pause() : resume())
  document.addEventListener('visibilitychange', onVisibility)

  return {
    get running() {
      return raf !== 0
    },
    start() {
      wanted = true
      resume()
    },
    stop() {
      wanted = false
      pause()
    },
    dispose() {
      disposed = true
      pause()
      io.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
    },
  }
}

/**
 * Device tiering for canvas effects. Crude, stable signals read once and cached —
 * not a benchmark loop, which would cost the first frames of the effect it is tuning.
 */

export type Tier = 1 | 2 | 3

type NavigatorWithHints = Navigator & { deviceMemory?: number }

let cached: Tier | null = null

export function tier(): Tier {
  if (cached !== null) return cached
  const nav = navigator as NavigatorWithHints
  const mem = nav.deviceMemory ?? 4
  const cores = navigator.hardwareConcurrency ?? 4
  const coarse = window.matchMedia?.('(pointer: coarse)').matches ?? false
  const narrow = window.innerWidth < 768
  if (coarse || narrow || mem <= 4) cached = 1
  else if (mem >= 8 && cores >= 8) cached = 3
  else cached = 2
  return cached
}

/** Cap device pixel ratio: the cheapest single performance lever. */
export function dprCap(max = 2): number {
  const cap = tier() === 1 ? 1.5 : max
  return Math.min(window.devicePixelRatio || 1, cap)
}
